-- =============================================================================
-- Vehicle hierarchy and part fitment, derived from OE part-number prefixes.
--
-- WHY THE FITMENT CHECKBOXES WERE ALL UNSELECTED: makes, models, generations,
-- engines, vehicles and part_fitment were ALL EMPTY (0 rows). There was nothing
-- to select. ProductForm was also reading the static 6-vehicle list in
-- lib/data.ts rather than the database, and admin-service returned
-- `fitment: []` hard-coded, so even populated fitment would not have shown.
--
-- HOW FITMENT IS DERIVED. Two kinds of prefix:
--   CHASSIS  (67 mapped)  8W0 -> A4 B9, 4M0 -> Q7 4M, ...
--            the part fits that generation, every year of it.
--   ENGINE   (32 mapped)  06L -> EA888 Gen3, which powers the A3 8V,
--            A4 B9, A5 F5, Q5 FY and TT 8S — so the part fits all of them.
--
-- COVERAGE: 234 of 260 parts (90%) mapped to 3927 fitment rows
-- across 368 vehicles and 39 generations.
--
-- THE 26 UNMAPPED PARTS, and why:
--   8MA (10), 0P2 (3), 4J3 (2), 4P0, 0AT, 95C — platform prefixes we have never
--     been able to identify across many search rounds. No fitment can be
--     asserted without knowing the platform.
--   N-numbers, WHT-, ZAW (7) — standard hardware and universal accessories.
--     These genuinely fit across the range; a per-vehicle row list would be
--     misleading precision rather than useful data.
--
-- IMPORTANT: fitment here is asserted at GENERATION level from the part number.
-- It is NOT engine-code-verified. Confirm against ETKA before relying on it for
-- a sale — this makes the checker useful, it does not make it authoritative.
-- =============================================================================

BEGIN;

